];
const lengths=[{
	name:"短篇",
	suffix:"/length-1"
},{
	name:"中篇",
	suffix:"/length-2"
},{
	name:"长篇",
	suffix:"/length-3"
}];
groups.forEach(group=>{
	group.types.forEach((type,typeIndex)=>{
